begin;
create or replace function public.app_config_save_patch(p_patch jsonb) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$ declare k text;v jsonb;begin if not public.is_admin() then raise exception 'Admin access required.' using errcode='insufficient_privilege';end if;if p_patch is null or jsonb_typeof(p_patch)<>'object' then raise exception 'Invalid configuration patch.' using errcode='invalid_parameter_value';end if;for k,v in select key,value from jsonb_each(p_patch) loop if length(k)>120 then raise exception 'Invalid configuration key.' using errcode='invalid_parameter_value';end if;insert into public.app_config(key,value) values(k,case when v='null'::jsonb then '' else trim(both '"' from v::text) end) on conflict(key) do update set value=excluded.value;end loop;end $$;
revoke execute on function public.app_config_save_patch(jsonb) from public,anon;grant execute on function public.app_config_save_patch(jsonb) to authenticated,service_role;
create or replace function public.finance_period_set_lock(p_period text,p_locked boolean) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$ declare normalized text:=trim(coalesce(p_period,''));actor text:=coalesce((select name from public.profiles where id=(select auth.uid())),(select auth.uid())::text);begin if not public.is_superadmin() then raise exception 'Super Admin access required.' using errcode='insufficient_privilege';end if;if normalized !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then raise exception 'Invalid financial period.' using errcode='invalid_parameter_value';end if;if p_locked then insert into public.fin_locks(period,locked_by) values(normalized,actor) on conflict(period) do update set locked_by=excluded.locked_by;else delete from public.fin_locks where period=normalized;end if;end $$;
revoke execute on function public.finance_period_set_lock(text,boolean) from public,anon;grant execute on function public.finance_period_set_lock(text,boolean) to authenticated,service_role;commit;
